    #{linkId} AS linkId,
    #{linkNodeId} AS linkNodeId,
    COUNT(DISTINCT CONCAT(node_code, '|', api_code, '|', execution_time)) AS totalCount,
    SUM(COALESCE(magnitude, 0)) AS totalMagnitude,
    MIN(execution_time) AS firstUpdateTime,
    MAX(execution_time) AS lastUpdateTime,
    1 AS updateCount
FROM mk_indicator
WHERE DATE(execution_time) = #{statDate}
  AND api_code = #{apiCode}
  AND node_code = #{nodeCode}
