UPDATE mk_node_statistics
SET total_count = (
    SELECT COUNT(DISTINCT CONCAT(node_code, '|', api_code, '|', execution_time))
    FROM mk_indicator
    WHERE DATE(execution_time) = #{statDate}
    AND api_code = #{apiCode}
    AND node_code = #{nodeCode}
    AND execution_time >= #{startTime}
    AND execution_time < #{endTime}
    ),
    total_magnitude = (
SELECT SUM(COALESCE(magnitude, 0))
FROM mk_indicator
WHERE DATE(execution_time) = #{statDate}
  AND api_code = #{apiCode}
  AND node_code = #{nodeCode}
  AND execution_time >= #{startTime}
  AND execution_time < #{endTime}
    ),
    first_update_time = (
SELECT MIN(execution_time)
FROM mk_indicator
WHERE DATE(execution_time) = #{statDate}
  AND api_code = #{apiCode}
  AND node_code = #{nodeCode}
  AND execution_time >= #{startTime}
  AND execution_time < #{endTime}
    ),
    last_update_time = (
SELECT MAX(execution_time)
FROM mk_indicator
WHERE DATE(execution_time) = #{statDate}
  AND api_code = #{apiCode}
  AND node_code = #{nodeCode}
  AND execution_time >= #{startTime}
  AND execution_time < #{endTime}
    ),
    update_count = update_count + 1
WHERE stat_date = #{statDate}
  AND api_code = #{apiCode}
  AND link_id = #{linkId}
  AND link_node_id = #{linkNodeId}

